// === Tab: mySketch.js ===
/*
It is a 2D shader made for the weekly Creative Coding Challenge
(https://openprocessing.org/curation/78544) on the theme "Things Fall Apart".

Both literally and figuratively.
*/

const scale = Math.max(1, devicePixelRatio)
let theShader

function preload(){
	theShader = loadShader('https://openprocessing.org/sketch/2908832/files/vert.glsl', 'frag.glsl')
}

function setup() {
	pixelDensity(scale)
	createCanvas(windowWidth, windowHeight, WEBGL)
}

function windowResized() {
	pixelDensity(scale)
	resizeCanvas(windowWidth, windowHeight)
}

function draw() {
  shader(theShader)
  theShader.setUniform("resolution", [width * scale, height * scale])
  theShader.setUniform("time", millis() / 1000.0)
  rect(0, 0, width, height)
}

// === Tab: vert.glsl ===
#version 300 es 
in vec3 aPosition; void main() { gl_Position=vec4(aPosition*2.-1., 1.0); }

// === Tab: frag.glsl ===
#version 300 es
/*********
* made by Matthias Hurrle (@atzedent)
*/
precision highp float;
out vec4 O;
uniform float time;
uniform vec2 resolution;
#define FC gl_FragCoord.xy
#define R resolution
#define T time
#define S smoothstep
#define SE(v,a) S(a+1./MN,a-1./MN,v)
#define SSE(v,a,k) S(a+k/MN,a-k/MN,v)
#define MN min(R.x,R.y)
#define TAU radians(360.)
#define light sqrt(S(.0,.0125,sin(-1.7+6.28318*fract(T*.1))*.5+.5))
float rnd(vec2 p) {
	p=fract(p*vec2(12.9898,78.233));
	p+=dot(p,p+34.56);
	return fract(p.x*p.y);
}
float noise(vec2 p) {
	vec2 i=floor(p), u=S(i,i+1.,p), k=vec2(1,0);
	float
	a=rnd(i),
	b=rnd(i+k),
	c=rnd(i+k.yx),
	d=rnd(i+k.xx);
	return mix(mix(a,b,u.x),mix(c,d,u.x),u.y);
}
float box(vec2 p, vec2 s, float r) {
	p=abs(p)-s+r;
	return length(max(p,.0))+min(.0,max(p.x,p.y))-r;
}
vec3 render(vec2 uv, vec2 o, float t) {
	float d=box(uv,uv-uv+.4,.005);
	d=SE(d,.0);
	uv+=o;
	uv.x*=.2;
	return uv.xxx-uv.xxx+d*noise(uv*4.-t+noise(uv*8.-t*.2+noise(uv*12.)));
}
void main() {
	vec2 uv=(FC-.5*R)/MN;
	if (T>2.) {
		float f=(.5+.5*sin(.1*TAU*T-TAU/3.+.5*rnd(round((FC/MN)*6.))))*30.;
		uv/=tanh(f);
	}
	vec2 p=uv;
	float t=T*.3;
	vec3 col=vec3(0),k=mix(vec3(150,226,255)/128.,vec3(255,34,25)/196.,SSE(p.x*3.+.75,.5*noise(uv*4.+noise(uv*2.-T*.2)),10.));
	col=mix(col,render(uv-.05,uv-uv,t),.5);
	col=mix(col,render(uv,uv+uv,t*2.+10.)*k,.5);
	col=mix(col,render(uv+.05,uv-10.,t-10.),.25);
	col=mix(vec3(0),col,min(time*.3,1.)*light*light);
	col=tanh(col*col);
	col=sqrt(col);
	O=vec4(col,1);
}

